import java.util.Map;

public class Hymns {

    public static void main(String[] args) throws Exception {
        HttpRequest request = new HttpRequest().setMethod("GET").setUrl("http://example.com");
        HttpRequestResponse response = request.send();

        // Output: {'message': 'test', 'timestamp': 1492390400}

        // More secure approach:
        HttpRequest request2 = new HttpRequest().setMethod("POST").setUrl("http://example.com");
        HttpRequestResponse response2 = request2.send();

        // Expects the same content as the original request
        Map<String, Object> params = request2.getParameterMap();
        System.out.println(params.get("message")); // Output: "test"
    }
}
```

