Here is a Python implementation of a rainbow table attack using the Python standard library. A rainbow table stores hashed passwords (one-way functions) and reconstructs plaintext from them. It is computationally infeasible for large datasets because it requires computing the original hash using a hash function.

```python
import hashlib
import random

class RainbowTable:
    """A rainbow table implementation."""
    def __init__(self):
        self.password = None

    def hash(self, password):
        """Encode password into a hash."""
        return hashlib.sha256(password.encode()).digest()

def create_rainbow_table(password_list):
    """Generate a hash table."""
    table = {}
    for password in password_list:
        table[password] = True

    return table

def reconstruct_password(table, plain_text):
    """Reconstruct a password from a hash."""
    for key in table.keys():
        if key in plain_text:
            return table[key]

def main():
    """Run the attack."""
    password_list = [
        "Secret123",
        "123456",
        "password123"
    ]
    table = create_rainbow_table(password_list)
    print(f"Rainbow table hashes: {table}")
    print(f"The password {password_list} is {reconstruct_password(table, password_list[0])}")

